import sys
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def perimeter(self):
        pass

class Triangle(Shape):
    def __init__(self, side1, side2, side3):
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3

    def perimeter(self):
        return self.side1 + self.side2 + self.side3

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    parts = line.split()
    if len(parts) < 4 or parts[0] != 'triangle':
        return
    try:
        side1 = float(parts[1])
        side2 = float(parts[2])
        side3 = float(parts[3])

        if side1 <= 0 or side2 <= 0 or side3 <= 0:
            return

        tri = Triangle(side1, side2, side3)
        print(f"Perimeter: {int(tri.perimeter())}")
    except:
        return

if __name__ == "__main__":
    main()
